/* ---------- STRATEGIES v2.9 : stockage fichier + strategie active en RAM ---------- */
function safeStrategyFilename(name){name=String(name||'').trim();if(!name)return null;name=name.replace(/\\/g,'/').split('/').pop().replace(/[^A-Za-z0-9._ -]/g,'_').replace(/\s+/g,' ').trim();if(!/\.(json|dat)$/i.test(name))name+='.dat';if(name.length>120){var ext=/\.json$/i.test(name)?'.json':'.dat';name=name.slice(0,120-ext.length)+ext;}return name;}
function normalizeStrategyDocument(doc){if(!doc||typeof doc!=='object'||Array.isArray(doc))throw new Error('Document de strategie invalide');if(doc.schema_version===1)return{strategy:doc,document:doc,format:'classic'};if(doc.iatb_executable&&doc.iatb_executable.schema_version===1)return{strategy:doc.iatb_executable,document:doc,format:'annex_dat'};throw new Error('Format de strategie non reconnu : schema_version=1 ou iatb_executable requis');}
function FileStrategyStore(dir){this.dir=dir;}
FileStrategyStore.prototype.list=function(){var self=this;return fs.readdirSync(self.dir).filter(function(n){return /\.(json|dat)$/i.test(n);}).sort().map(function(n){var p=path.join(self.dir,n),st=fs.statSync(p),fmt=/\.dat$/i.test(n)?'DAT':'JSON';return{filename:n,format:fmt,size:st.size,modifiedAt:st.mtime.toISOString()};});};
