FileStrategyStore.prototype.write=function(name,strategy,document){var fn=safeStrategyFilename(name);if(!fn)throw new Error('Nom de strategie invalide');var p=path.join(this.dir,fn),tmp=p+'.tmp',payload=document||strategy;if(/\.dat$/i.test(fn)&&document&&document.iatb_executable)payload=document;var txt=JSON.stringify(payload,null,2)+'\n';fs.writeFileSync(tmp,txt,'utf8');fs.renameSync(tmp,p);return{filename:fn,size:Buffer.byteLength(txt),format:/\.dat$/i.test(fn)?'DAT':'JSON'};};
var STRATEGY_STORE=new FileStrategyStore(STRAT_DIR);
var STRATEGY_OPS={'<':1,'<=':1,'>':1,'>=':1,'==':1,'!=':1,'crosses_above':1,'crosses_below':1};
function strategyNumber(v){return typeof v==='number'&&isFinite(v);}
function validateStrategy(s){var e=[];if(!s||typeof s!=='object'||Array.isArray(s))return{ok:false,errors:['Le contenu doit etre un objet JSON']};if(s.schema_version!==1)e.push('schema_version doit etre 1');if(!s.name||typeof s.name!=='string'||s.name.length>80)e.push('name requis (80 caracteres max)');if(!s.version||typeof s.version!=='string'||s.version.length>20)e.push('version requise');var ex=String(s.exchange||'GMX').toUpperCase();if(ex!=='GMX'&&ex!=='BINANCE')e.push('exchange doit etre GMX (BINANCE legacy accepte pour migration)');if(!normalizeGmxSymbol(String(s.symbol||'')))e.push('symbol GMX invalide');if(!ints[s.timeframe])e.push('timeframe invalide');if(!s.indicators||typeof s.indicators!=='object'||Array.isArray(s.indicators))e.push('indicators requis');else Object.keys(s.indicators).forEach(function(k){var x=s.indicators[k],n=k.toLowerCase();if(!x||typeof x!=='object')return e.push('indicateur '+k+' invalide');if(n==='rsi'&&(!strategyNumber(x.period)||x.period<2||x.period>200))e.push('RSI period doit etre entre 2 et 200');if(n==='ema'&&(!strategyNumber(x.period)||x.period<2||x.period>500))e.push('EMA period doit etre entre 2 et 500');});function checkRule(block,label){if(!block||typeof block!=='object')return e.push(label+' requis');if(block.conditions&&!Array.isArray(block.conditions))e.push(label+'.conditions doit etre un tableau');(block.conditions||[]).forEach(function(c,i){if(!c||typeof c!=='object')return e.push(label+' condition '+i+' invalide');if(!c.indicator||typeof c.indicator!=='string')e.push(label+' condition '+i+': indicator requis');if(!STRATEGY_OPS[c.operator])e.push(label+' condition '+i+': operator invalide');if(!strategyNumber(c.value))e.push(label+' condition '+i+': value numerique requise');});}checkRule(s.entry,'entry');checkRule(s.exit,'exit');if(s.entry&&s.entry.side&&!/^(BUY|SELL)$/.test(String(s.entry.side).toUpperCase()))e.push('entry.side doit etre BUY ou SELL');if(!s.risk||typeof s.risk!=='object')e.push('risk requis');else{if(!strategyNumber(s.risk.leverage)||s.risk.leverage<1||s.risk.leverage>50)e.push('risk.leverage doit etre entre 1 et 50');if(!strategyNumber(s.risk.max_position_usdt)||s.risk.max_position_usdt<=0)e.push('risk.max_position_usdt doit etre > 0');if(s.risk.stop_loss_percent!=null&&(!strategyNumber(s.risk.stop_loss_percent)||s.risk.stop_loss_percent<=0||s.risk.stop_loss_percent>50))e.push('risk.stop_loss_percent invalide');if(s.risk.take_profit_percent!=null&&(!strategyNumber(s.risk.take_profit_percent)||s.risk.take_profit_percent<=0||s.risk.take_profit_percent>500))e.push('risk.take_profit_percent invalide');}return{ok:e.length===0,errors:e};}
function compileStrategy(s){var v=validateStrategy(s);if(!v.ok){var er=new Error('Strategie invalide');er.validation=v;throw er;}var copy=JSON.parse(JSON.stringify(s));copy.symbol=normalizeGmxSymbol(copy.symbol);copy.exchange='GMX';return{schemaVersion:copy.schema_version,name:copy.name,version:copy.version,exchange:'GMX',symbol:copy.symbol,timeframe:copy.timeframe,indicators:copy.indicators||{},entry:copy.entry,exit:copy.exit,risk:copy.risk,raw:copy};}
function strategyHash(s){return crypto.createHash('sha256').update(JSON.stringify(s)).digest('hex');}
var STRATEGY_MANAGER={active:null,compiled:null,document:null,format:null,filename:null,hash:null,loadedAt:null,state:'STOPPED',lastError:null,loadObject:function(filename,s,document,format){var c=compileStrategy(s);this.active=JSON.parse(JSON.stringify(c.raw));this.compiled=c;this.document=document?JSON.parse(JSON.stringify(document)):JSON.parse(JSON.stringify(c.raw));this.format=format||'classic';this.filename=safeStrategyFilename(filename)||'memory_strategy.dat';this.hash=strategyHash(this.document);this.loadedAt=new Date().toISOString();this.state='STOPPED';this.lastError=null;log('STRATEGY','Strategie chargee en RAM',this.filename+' '+c.name+' v'+c.version+' format='+this.format);return this.info();},loadFile:function(filename){var x=STRATEGY_STORE.read(filename);return this.loadObject(x.filename,x.strategy,x.document,x.format);},reload:function(){if(!this.filename)throw new Error('Aucune strategie chargee');return this.loadFile(this.filename);},start:function(){if(!this.compiled)throw new Error('Charge une strategie avant de demarrer');this.state='RUNNING';log('STRATEGY','Strategie activee en RAM',this.compiled.name);return this.info();},pause:function(){if(!this.compiled)throw new Error('Aucune strategie chargee');if(this.state!=='RUNNING')throw new Error('La strategie doit etre RUNNING');this.state='PAUSED';log('STRATEGY','Strategie en pause',this.compiled.name);return this.info();},stop:function(){if(!this.compiled)throw new Error('Aucune strategie chargee');this.state='STOPPED';log('STRATEGY','Strategie arretee',this.compiled.name);return this.info();},info:function(){return{loaded:!!this.active,filename:this.filename,format:this.format,hash:this.hash,loadedAt:this.loadedAt,state:this.state,lastError:this.lastError,strategy:this.active?{schema_version:this.active.schema_version,name:this.active.name,version:this.active.version,exchange:this.active.exchange||'GMX',symbol:this.active.symbol,timeframe:this.active.timeframe,indicators:this.active.indicators||{},entry:this.active.entry||{},exit:this.active.exit||{},risk:this.active.risk||{}}:null,annexDocument:this.format==='annex_dat'&&this.document?{schema:this.document.schema||'',strategy_id:this.document.strategy_id||'',purpose:this.document.purpose||'',status:this.document.status||''}:null};}};
